"use client";

import * as ScrollAreaPrimitive from "@radix-ui/react-scroll-area";

import { cn } from "@/lib/utils";

const ScrollArea = ({
  className,
  children,
  ...props
}: React.ComponentProps<typeof ScrollAreaPrimitive.Root>) => (
  <ScrollAreaPrimitive.Root
    data-slot="scroll-area"
    className={cn("relative", className)}
    {...props}
  >
    <ScrollAreaPrimitive.Viewport
      data-slot="scroll-area-viewport"
      className="focus-visible:ring-ring/50 size-full rounded-[inherit] transition-[color,box-shadow] outline-none focus-visible:ring-[3px]"
    >
      {children}
    </ScrollAreaPrimitive.Viewport>
    <ScrollBar />
    <ScrollAreaPrimitive.Corner />
  </ScrollAreaPrimitive.Root>
);

const ScrollBar = ({
  className,
  orientation = "vertical",
  ...props
}: React.ComponentProps<typeof ScrollAreaPrimitive.Scrollbar>) => (
  <ScrollAreaPrimitive.Scrollbar
    data-slot="scroll-area-scrollbar"
    orientation={orientation}
    className={cn(
      "flex touch-none p-px transition-colors select-none",
      orientation === "vertical" && "h-full w-2.5 border-l border-l-transparent",
      orientation === "horizontal" && "h-2.5 flex-col border-t border-t-transparent",
      className,
    )}
    {...props}
  >
    <ScrollAreaPrimitive.Thumb
      data-slot="scroll-area-thumb"
      className="bg-border relative flex-1 rounded-full"
    />
  </ScrollAreaPrimitive.Scrollbar>
);

export { ScrollArea, ScrollBar };
export default ScrollArea;

import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";

const tags = Array.from({ length: 50 }, (_, i) => `Component ${i + 1}`);

const artworks = [
  { artist: "Charlie Parker", title: "Ornithology" },
  { artist: "Miles Davis", title: "So What" },
  { artist: "Bill Evans", title: "Waltz for Debby" },
  { artist: "John Coltrane", title: "A Love Supreme" },
  { artist: "Dave Brubeck", title: "Take Five" },
  { artist: "Miles Davis", title: "Kind of Blue" },
  { artist: "John Coltrane", title: "Giant Steps" },
  { artist: "Herbie Hancock", title: "Maiden Voyage" },
];

export function ScrollAreaDemo() {
  return (
    <div className="flex gap-6">
      {/* Vertical */}
      <ScrollArea className="h-72 w-48 rounded-md border">
        <div className="p-4">
          <h4 className="mb-4 text-sm font-medium leading-none">Tags</h4>
          {tags.map((tag) => (
            <div key={tag}>
              <p className="text-sm">{tag}</p>
              <Separator className="my-2" />
            </div>
          ))}
        </div>
      </ScrollArea>

      {/* Horizontal */}
      <ScrollArea className="w-64 rounded-md border">
        <div className="flex gap-4 p-4">
          {artworks.map((artwork) => (
            <figure key={artwork.title} className="shrink-0">
              <div className="overflow-hidden rounded-md">
                <div className="size-[150px] bg-muted" />
              </div>
              <figcaption className="pt-2 text-xs text-muted-foreground">
                <span className="font-medium text-foreground block truncate w-[150px]">
                  {artwork.title}
                </span>
                {artwork.artist}
              </figcaption>
            </figure>
          ))}
        </div>
        <ScrollBar orientation="horizontal" />
      </ScrollArea>
    </div>
  );
}


export default function Page() {
  return (
    <div className="flex min-h-svh items-center justify-center p-8 bg-background">
      <ScrollAreaDemo />
    </div>
  );
}
